:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c63ff;
  --accent-hover: #5a52e0;
  --accent-pressed: #4a43c0;
  --border: #44445a;
  --locked: #ffb347;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 640px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 8px;
  letter-spacing: -0.02em;
}

.subtitle {
  font-size: 1rem;
  color: #a0a0b8;
  margin-bottom: 24px;
}

.palette {
  display: flex;
  gap: 12px;
  margin-bottom: 28px;
  flex-wrap: wrap;
  justify-content: center;
}

.swatch {
  flex: 1 1 100px;
  min-width: 100px;
  border-radius: var(--radius);
  overflow: hidden;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
  display: flex;
  flex-direction: column;
  transition: transform 0.15s ease;
}

.swatch:hover {
  transform: translateY(-2px);
}

.swatch-color {
  height: 100px;
  width: 100%;
}

.swatch-info {
  background: var(--card-bg);
  padding: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.hex {
  font-family: 'Courier New', monospace;
  font-size: 0.9rem;
  color: var(--text);
  letter-spacing: 0.5px;
}

.lock-btn {
  background: none;
  border: 1px solid var(--border);
  border-radius: 6px;
  color: var(--text);
  cursor: pointer;
  padding: 4px 6px;
  font-size: 0.85rem;
  line-height: 1;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
}

.lock-btn:hover {
  background: var(--border);
}

.lock-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.lock-btn[aria-pressed="true"] {
  background: var(--locked);
  border-color: var(--locked);
  color: #1e1e2f;
}

.lock-btn:active {
  transform: scale(0.95);
}

.btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 14px 28px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
  width: 100%;
  max-width: 320px;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.btn:active {
  background: var(--accent-pressed);
  transform: scale(0.98);
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 480px) {
  .card {
    padding: 16px;
  }
  h1 {
    font-size: 1.5rem;
  }
  .swatch {
    flex: 1 1 80px;
    min-width: 80px;
  }
  .swatch-color {
    height: 80px;
  }
  .hex {
    font-size: 0.8rem;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');
  const statusEl = document.getElementById('status');

  const SWATCH_COUNT = 5;
  let colors = [];
  let locked = [false, false, false, false, false];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`;
  }

  function generateHarmoniousPalette() {
    const baseHue = Math.floor(Math.random() * 360);
    const scheme = Math.floor(Math.random() * 3);
    const hues = [];

    if (scheme === 0) {
      const offsets = [0, 30, 60, 180, 210];
      offsets.forEach((o) => hues.push((baseHue + o) % 360));
    } else if (scheme === 1) {
      const offsets = [0, 120, 240, 60, 180];
      offsets.forEach((o) => hues.push((baseHue + o) % 360));
    } else {
      const offsets = [0, 45, 90, 135, 180];
      offsets.forEach((o) => hues.push((baseHue + o) % 360));
    }

    return hues.map((h) => {
      const s = 50 + Math.floor(Math.random() * 30);
      const l = 40 + Math.floor(Math.random() * 30);
      return hslToHex(h, s, l);
    });
  }

  function render() {
    paletteEl.innerHTML = '';
    colors.forEach((hex, i) => {
      const swatch = document.createElement('div');
      swatch.className = 'swatch';
      swatch.setAttribute('role', 'listitem');

      const colorDiv = document.createElement('div');
      colorDiv.className = 'swatch-color';
      colorDiv.style.backgroundColor = hex;

      const infoDiv = document.createElement('div');
      infoDiv.className = 'swatch-info';

      const hexSpan = document.createElement('span');
      hexSpan.className = 'hex';
      hexSpan.textContent = hex.toUpperCase();

      const lockBtn = document.createElement('button');
      lockBtn.className = 'lock-btn';
      lockBtn.type = 'button';
      lockBtn.setAttribute('aria-pressed', String(locked[i]));
      lockBtn.setAttribute('aria-label', `Lock color ${hex.toUpperCase()}`);
      lockBtn.textContent = locked[i] ? '🔒' : '🔓';

      lockBtn.addEventListener('click', () => {
        locked[i] = !locked[i];
        render();
        statusEl.textContent = `Color ${hex.toUpperCase()} ${locked[i] ? 'locked' : 'unlocked'}`;
      });

      infoDiv.appendChild(hexSpan);
      infoDiv.appendChild(lockBtn);
      swatch.appendChild(colorDiv);
      swatch.appendChild(infoDiv);
      paletteEl.appendChild(swatch);
    });
  }

  function generateNewPalette() {
    const newColors = generateHarmoniousPalette();
    for (let i = 0; i < SWATCH_COUNT; i++) {
      if (!locked[i]) {
        colors[i] = newColors[i];
      }
    }
    render();
    statusEl.textContent = 'New palette generated';
  }

  function init() {
    colors = generateHarmoniousPalette();
    render();
    generateBtn.addEventListener('click', generateNewPalette);
  }

  init();
})();
